'use strict';
const storyTasks=[
{icon:'🚧',job:'운송 관리자',title:'안전한 길 연결',question:'급식 재료를 실은 차가 출발하려는데 도로 일부가 잠겼어요. 어떤 계획이 필요할까요?',answers:['시간을 맞추기 위해 잠긴 길로 바로 출발해요','통제 구간을 확인하고 안전한 우회 경로를 정해요','물건을 더 많이 실으면 도로를 빨리 통과할 수 있어요'],correct:1,why:'운송 관리자는 물건만 옮기는 것이 아니라, 사람과 물건이 안전하게 도착할 경로를 계획해요.'},
{icon:'💡',job:'전력 설비 기술자',title:'냉장 창고에 전기 공급',question:'폭우 뒤 냉장 창고의 전원이 꺼졌어요. 마을 주민은 어떻게 도와야 할까요?',answers:['위험 구역에 들어가지 않고 설비 기술자에게 점검을 요청해요','젖은 전선을 직접 연결해요','상태를 확인하지 않고 전원을 계속 켜요'],correct:0,why:'전력 설비 기술자의 안전 점검과 복구가 있어야 생산물도 안전하게 보관할 수 있어요. 실제 전기 설비는 직접 만지지 않아요.'},
{icon:'🔎',job:'품질 관리자',title:'급식 재료 검수',question:'재료가 모두 모였어요. 급식 담당자에게 보내기 전에 무엇을 확인할까요?',answers:['상자의 개수만 맞으면 돼요','포장이 예쁜 재료만 골라요','보관 상태·포장 손상·소비기한과 수량을 함께 확인해요'],correct:2,why:'품질 관리자는 눈에 잘 보이지 않는 문제도 살펴요. 생산과 운송 뒤에도 안전하게 사용할 수 있는지 확인하는 일이 필요해요.'},
{icon:'🚚',job:'배송·급식 담당자',title:'내일 아침 급식 인계',question:'검수를 마친 재료를 급식실로 보내요. 마지막으로 어떤 일을 해야 할까요?',answers:['입구에 두고 도착했다고 생각해요','재료와 검수 기록을 담당자에게 인계하고 수령을 확인해요','친구가 알아서 가져갈 때까지 기다려요'],correct:1,why:'배송 담당자의 인계와 급식 담당자의 수령 확인까지 이어져야, 여러 사람의 일이 한 끼로 완성돼요.'}
];
function currentMission(){return window.classroomActive?classroomData.mission:state.storyMission||null}
window.missionVisual=()=>{const m=currentMission();return {active:!!m,road:!m||m.counts[0]>=m.target,power:!m||m.counts[1]>=m.target,complete:!!m?.completed}}
function missionStage(m){if(m.completed)return '급식 준비 완료';if(m.counts[0]<m.target||m.counts[1]<m.target)return '1단계 · 길과 전기 복구';if(m.food.some(n=>n<m.goal))return '2단계 · 재료 모으기';if(m.counts[2]<m.target)return '3단계 · 품질 검수';return '4단계 · 급식실 인계'}
function missionUnlocked(m,i){return i<2||(m.counts[0]>=m.target&&m.counts[1]>=m.target&&m.food.every(n=>n>=m.goal)&&(i===2||m.counts[2]>=m.target))}
function myMissionWork(m){return m.helpers.find(h=>h.actor===(window.classroomActive?classroomData.me.id:'demo'))?.work||{}}
const beforeStoryPanel=renderPanel;renderPanel=function(){if(tab!=='season'){delete $('#panel').dataset.missionSignature;beforeStoryPanel();return}const m=currentMission(),panel=$('#panel');const signature=JSON.stringify([m?.revision,m?.target,m?.goal,m?.food,m?.counts,m?.completed,state.stock,state.storyDemoSupplied,window.classroomActive,schoolPending,schoolOnline,classroomData?.room?.paused]);if(panel.dataset.missionSignature===signature)return;drawMissionPanel();panel.dataset.missionSignature=signature};
const beforeStoryUI=updateGameUI;updateGameUI=function(){beforeStoryUI();const m=currentMission();objective.innerHTML=`<span class="objective-icon">${m?.completed?'🎉':'🌧️'}</span><span><small>첫 협력 이야기${m?' · '+missionStage(m):' · 15~20분 활동'}</small><b>${m?.completed?'우리의 일이 모여 급식이 완성됐어요':'폭우로 멈춘 마을, 내일 아침 급식을 부탁해!'}</b></span><span class="objective-arrow">${m?'이어서 하기':'이야기 보기'} →</span>`;document.querySelectorAll('[data-story-task],[data-story-gift],#storyAnswerSubmit').forEach(b=>{if(window.classroomActive&&schoolPending){if(!b.disabled){b.dataset.storyPending='1';b.disabled=true}}else if(b.dataset.storyPending){delete b.dataset.storyPending;b.disabled=false}})};
function drawMissionPanel(){const m=currentMission();if(!m){$('#panel').innerHTML=`<span class="eyetag">EPISODE 01 · 함께 만드는 한 끼</span><h2>내일 아침 급식을 부탁해!</h2><div class="story-cover">🌧️ 🚧 🏘️</div><p>밤사이 내린 폭우로 도로가 막히고 냉장 창고의 전기가 끊겼어요. 내일 아침 급식에 쓸 재료가 도착할 수 있도록 마을의 여러 직업과 힘을 모아 주세요.</p><ol class="story-intro"><li>운송·전력 직업 미션으로 길과 창고 복구</li><li>생산하고 장터에서 교환해 네 가지 재료 모으기</li><li>품질 검수와 인계로 급식 준비 완료</li></ol>${window.classroomActive?'<div class="notice">선생님이 운영실에서 이야기를 시작하면 우리 반이 함께 참여할 수 있어요.</div>':'<button class="primary wide" id="startDemoStory">혼자 이야기 연습하기</button><p class="field-hint">연습에서는 필요한 참여 수가 1명이에요. 학급 기록과 분리되어 이 기기에 저장돼요.</p>'}`;if($('#startDemoStory'))$('#startDemoStory').onclick=()=>{if(state.job===null){showJobs();return}state.storyMission={target:1,goal:2,food:[0,0,0,0],started:Date.now(),completed:0,counts:[0,0,0,0],helpers:[]};state.day=4;save();render()};return}
const work=myMissionWork(m),busy=window.classroomActive&&(schoolPending||!schoolOnline||classroomData.room.paused),ready=m.counts[0]>=m.target&&m.counts[1]>=m.target;$('#panel').innerHTML=`<span class="eyetag">EPISODE 01 · ${missionStage(m)}</span><h2>${m.completed?'함께 만든 아침!':'내일 아침 급식을 부탁해!'}</h2><p>${m.completed?'생산·운송·전력·검수·급식 인계가 모두 이어졌어요. 아래에서 우리가 보탠 일을 확인해 보세요.':'각 직업 미션에 '+m.target+'명의 서로 다른 참여가 필요해요. 이번 수업 참여 인원이 적다면 선생님이 목표를 낮출 수 있어요. 내 직업과 달라도 다른 역할을 탐험할 수 있어요.'}</p>${m.completed?'<div class="story-finish">🎉<b>우리 마을 급식 준비 완료</b><span>한 사람의 수확에서 모두의 한 끼로</span></div>':''}<div class="story-steps">${storyTasks.map((t,i)=>`<button data-story-task="${i}" ${busy||m.completed||work[i]||!missionUnlocked(m,i)?'disabled':''} class="story-task ${m.counts[i]>=m.target?'done':''}"><span>${t.icon}</span><div><b>${t.title}</b><small>${t.job} · ${Math.min(m.counts[i],m.target)}/${m.target}명 ${work[i]?'· 내가 참여함':!missionUnlocked(m,i)?'· 앞 단계 먼저':''}</small></div><em>${m.counts[i]>=m.target?'✓':'→'}</em></button>`).join('')}</div><h3 class="story-subhead">🥬 함께 모으는 급식 재료</h3><p class="field-hint">${ready?'필요한 재료는 친구와 교환해도 좋아요. 보탠 재료는 급식 준비에 사용됩니다.':'길과 창고를 복구하면 재료를 보탤 수 있어요.'}</p>${items.slice(0,4).map((name,i)=>`<div class="story-supply"><span>${symbols[i]} ${name}<small>${m.food[i]}/${m.goal}개 · 내 보관 ${state.stock[i]}개</small></span><button data-story-gift="${i}" ${busy||!ready||m.completed||m.food[i]>=m.goal||state.stock[i]<1?'disabled':''}>1개 보태기</button></div>`).join('')}<div class="dialog-actions"><button id="storyMarket">장터 가기</button><button id="storyMap">복구된 마을 보기</button></div>${!window.classroomActive&&!m.completed?'<button class="wide" id="demoStoryFood">연습용 재료 받기 · 각 2개</button>':''}<h3 class="story-subhead">우리가 보탠 일</h3><div class="story-credits">${m.helpers.length?m.helpers.map(h=>{const person=window.classroomActive?classroomData.players.find(p=>p.id===h.actor):{name:state.name};return `<div><b>${escapeHtml(person?.name||'마을 친구')}</b><small>${Object.entries(h.work).map(([kind,n])=>Number(kind)<4?storyTasks[kind].job:items[Number(kind)-4]+' '+n+'개').join(' · ')}</small></div>`}).join(''):'<p>첫 번째 연결을 만들어 주세요.</p>'}</div>${m.completed?'<div class="notice">함께 이야기해요: 내 일을 가능하게 한 다른 직업은 무엇이었나요? 그 일이 멈추면 누구의 하루가 달라질까요?</div>':''}`;$('#storyMarket').onclick=()=>gameNavigate('market');$('#storyMap').onclick=()=>gameNavigate('village');document.querySelectorAll('[data-story-task]').forEach(b=>b.onclick=()=>openStoryTask(Number(b.dataset.storyTask)));document.querySelectorAll('[data-story-gift]').forEach(b=>b.onclick=()=>performStoryAction('mission_donate',Number(b.dataset.storyGift)));if($('#demoStoryFood'))$('#demoStoryFood').onclick=()=>{if(state.storyDemoSupplied){toast('연습 재료는 이미 받았어요. 생산하거나 교환해 주세요.');return}state.stock=state.stock.map(n=>n+2);state.storyDemoSupplied=true;save();render();toast('연습용 재료를 각 2개 받았어요. 학급 플레이에는 지급되지 않아요.')}}
function openStoryTask(i){const t=storyTasks[i];modal(`<div class="menu-heading"><span>CAREER MISSION · ${t.job}</span><button data-close aria-label="미션 닫기">×</button></div><h2>${t.icon} ${t.title}</h2><p>${t.question}</p><form id="storyQuiz">${t.answers.map((a,n)=>`<label class="story-choice"><input type="radio" name="storyAnswer" value="${n}" required><span>${a}</span></label>`).join('')}<p id="storyFeedback" role="status"></p><button class="primary wide" id="storyAnswerSubmit" type="submit">내 생각으로 힘 보태기 · +10코인</button></form>`);$('#storyQuiz').onsubmit=async e=>{e.preventDefault();const answer=Number(new FormData(e.target).get('storyAnswer'));if(answer!==t.correct){$('#storyFeedback').textContent='다시 생각해 보세요. '+t.why;return}const ok=await performStoryAction('mission_task',i,answer);if(ok){modal(`<span class="eyetag">직업 미션 참여 완료</span><h2>${t.icon} 내 일이 마을에 닿았어요</h2><p>${t.why}</p><div class="notice">서로 다른 친구들의 참여가 목표에 도달하면 마을이 바뀝니다. 다른 역할도 탐험해 보세요.</div><button class="primary wide" id="storyContinue">우리 반 진행 보기</button>`);$('#storyContinue').onclick=()=>{close();gameNavigate('season')}}else if($('#storyFeedback'))$('#storyFeedback').textContent='이미 참여했거나 상태가 바뀌었어요. 미션 목록을 다시 확인해 주세요.'};updateGameUI()}
async function performStoryAction(action,item,answer){if(window.classroomActive)return schoolAction({action,item,answer,qty:1});const m=currentMission();if(!m||m.completed)return false;let h=m.helpers.find(h=>h.actor==='demo');if(!h){h={actor:'demo',work:{}};m.helpers.push(h)}if(action==='mission_task'){if(h.work[item]||!missionUnlocked(m,item)||answer!==storyTasks[item].correct)return false;h.work[item]=1;m.counts[item]++;state.coins+=10;if(item===3&&m.counts[3]>=m.target)m.completed=Date.now()}else{if(m.counts[0]<m.target||m.counts[1]<m.target||state.stock[item]<1||m.food[item]>=m.goal)return false;state.stock[item]--;m.food[item]++;h.work[item+4]=(h.work[item+4]||0)+1}if(m.counts[0]>=m.target&&m.counts[1]>=m.target)state.day=5;save();render();return true}
const beforeStoryMarket=marketOpen;marketOpen=function(){const m=currentMission();return !window.classroomActive&&m?m.counts[0]>=m.target:beforeStoryMarket()};
render();
